+using static StrataLint.Scribe.DefinitionDsl;
+namespace StrataLint.Scribe.Blueprint.D5.S3.VertexAlgebra.Lattice;
+internal sealed class LatticeNullFrameExistenceDocument : IScribeDocumentDefinition
+{
+    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
+        "Original lattice light-cone algebra", H("LatticeNullFrameExistence"), Blocks(
+        Paragraph(Text("The actual inverse-Gram equation and complex algebraic closure give charge-dependent light-cone frames. The transverse dimension and basis are derived from the explicit frame equivalence, without a supplied splitting certificate. This is complex bilinear algebra on the original carrier, not an integral lattice isometry or a positive-form assertion.")),
+        Describe.Lean(DescribeId.Create("latticenullframeexistence-0"), DeclarationHandle.Create("D5/S3/VertexAlgebra/Lattice/LatticeNullFrameExistence.gramBilin_nondegenerate"), H("gramBilin_nondegenerate"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every original even integral symmetric D and complex matrix H with H * gramComplex D = 1, the actual complex Gram bilinear form is nondegenerate. This is derived from determinants of the inverse equation, not assumed from rank."))), DescribeRole.Theorem),
+        Describe.Lean(DescribeId.Create("latticenullframeexistence-1"), DeclarationHandle.Create("D5/S3/VertexAlgebra/Lattice/LatticeNullFrameExistence.exists_nullFrame_pPlus_ne_zero"), H("exists_nullFrame_pPlus_ne_zero"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every original D, complex H with H * gramComplex D = 1, rank at least two, and nonzero original integral p:Charge D, there exists an actual NullFrame D with pPlus(p) nonzero. A Mathlib orthogonal basis and a complex square root construct a null vector detected by p, then a genuinely paired vector is normalized and its self-pairing removed. The frame may depend on p. Zero charge is excluded; no uniform frame or positivity is asserted."))), DescribeRole.Theorem),
+        Describe.Lean(DescribeId.Create("nullframe-exact-transverse-dimension"), DeclarationHandle.Create("D5/S3/VertexAlgebra/Lattice/LatticeNullFrameExistence.finrank_K_add_two"), H("Exact transverse dimension"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every original D and every actual NullFrame F, finrank of its actual simultaneous Gram-orthogonal complement plus two equals D.rank. This is derived from the explicit frameEquiv and finite-dimensional product arithmetic; it has no inverse-Gram premise and assumes no basis or complement certificate."))), DescribeRole.Theorem),
+        Describe.Lean(DescribeId.Create("nullframe-derived-transverse-basis"), DeclarationHandle.Create("D5/S3/VertexAlgebra/Lattice/LatticeNullFrameExistence.transverseBasis"), H("Basis of the actual transverse subspace"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every original D and actual F, the chosen finite-dimensional basis of the actual F.K is reindexed by the proved dimension equality to Fin(D.rank-2). At rank 26 this gives an actual Fin 24 basis. It does not orthogonalize or replace the integral charge lattice."))), DescribeRole.Definition))));
+}
